{
  "description": "The creature is a standing chimera shown in right-facing profile against a plain light background, with the head, hindquarters, hind legs and long bushy tail of a reddish-brown fox combined with the feathered torso and folded wings of an owl. The fox head with pointed ears and a white muzzle sits atop a thickly feathered chest and back, the white and mottled tan-grey-brown plumage covering the throat, breast and sides and continuing into two large folded wings held close to the body. The lower belly, hips and two bent hind legs are covered in dense fox fur, and a long, full, fox-like tail extends straight back behind the legs. The animal stands on its hind paws on a small patch of bare ground with sparse tufts of grass, outlined by a faint dashed line around its entire silhouette.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a fox head with a pointed snout, black nose, amber eyes, reddish-brown fur on the crown and cheeks and white fur on the muzzle, chin and throat, facing to the right",
      "where": "at the top front of the body, above the feathered chest"
    },
    {
      "part": "ears",
      "looks_like": "two upright, triangular, pointed ears with reddish-brown outer fur and darker interior fur, with fine hairs along the edges",
      "where": "on top of the head, one slightly forward of the other in profile"
    },
    {
      "part": "legs",
      "looks_like": "two muscular, digitigrade hind legs covered in short reddish-brown fur shading to lighter tan on the inner thigh and greyer on the lower shank, bent at the hock joint",
      "where": "under the rear torso, supporting the body from below"
    },
    {
      "part": "feet",
      "looks_like": "two hind paws with dark pads, blunt claws and slightly shaggy fur on the ankles, with visible toes",
      "where": "at the bottom ends of the hind legs, planted on the ground"
    },
    {
      "part": "tail",
      "looks_like": "a long, thick, bushy tail covered in dense reddish-brown fur with a paler, almost white tip and a darker underside",
      "where": "extending horizontally backward from the rump, behind and slightly between the hind legs"
    },
    {
      "part": "wings",
      "looks_like": "two large, folded bird wings with layered flight feathers patterned in cream, tan, grey and black with dark spots and barring, the primaries overlapping toward the rear",
      "where": "along the left and right sides of the torso, from the shoulder region back over the flank, partially covering the hindquarters"
    },
    {
      "part": "feathers",
      "looks_like": "dense, overlapping soft feathers; white and cream with small dark speckles on the chest and throat, and mottled tan, grey and brown with intricate scalloped patterning on the back and wing coverts",
      "where": "covering the neck, chest, breast, back and the entire surface of both wings"
    },
    {
      "part": "markings",
      "looks_like": "small scattered black and dark brown spots and speckles, plus darker barring on the flight feathers",
      "where": "across the white chest feathers, the throat, the upper back and the wing feathers"
    }
  ],
  "attached_objects": [],
  "animals": [
    "fox",
    "owl"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 2,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
